from azure.identity import DefaultAzureCredential
from azure.keyvault.keys import KeyClient
from azure.keyvault.keys.crypto import CryptographyClient
import os

def get_key_vault_url():
    key_vault_url = os.environ.get("KEY_VAULT_URL")
    if not key_vault_url:
        raise ValueError("KEY_VAULT_URL environment variable not set.")
    return key_vault_url

def get_key_client():
    key_vault_url = get_key_vault_url()
    credential = DefaultAzureCredential()
    return KeyClient(vault_url=key_vault_url, credential=credential)

def get_cryptography_client(key_id):
    credential = DefaultAzureCredential()
    return CryptographyClient(key_id=key_id, credential=credential)

def get_text_analytics_client():
    from azure.core.credentials import AzureKeyCredential
    from azure.ai.textanalytics import TextAnalyticsClient
    text_analytics_endpoint = os.environ.get("TEXT_ANALYTICS_ENDPOINT")
    text_analytics_key = os.environ.get("TEXT_ANALYTICS_KEY")
    if not text_analytics_endpoint or not text_analytics_key:
        raise ValueError("TEXT_ANALYTICS_ENDPOINT and TEXT_ANALYTICS_KEY environment variables must be set.")
    return TextAnalyticsClient(endpoint=text_analytics_endpoint, credential=AzureKeyCredential(text_analytics_key))

def get_translator_client():
    from azure.ai.translation.text import TextTranslationClient
    from azure.ai.translation.text.models import TextTranslationInput
    from azure.core.credentials import AzureKeyCredential
    translator_endpoint = os.environ.get("TRANSLATOR_ENDPOINT")
    translator_key = os.environ.get("TRANSLATOR_KEY")
    translator_region = os.environ.get("TRANSLATOR_REGION")
    if not translator_endpoint or not translator_key or not translator_region:
        raise ValueError("TRANSLATOR_ENDPOINT, TRANSLATOR_KEY, and TRANSLATOR_REGION environment variables must be set.")
    return TextTranslationClient(endpoint=translator_endpoint, credential=AzureKeyCredential(translator_key), region=translator_region)

import json

def serialize_payload(data):
    # Basic serialization for consistency
    return json.dumps(data).encode('utf-8')

def deserialize_payload(data):
    # Basic deserialization for consistency
    return json.loads(data.decode('utf-8'))

from security_client import get_cryptography_client
from azure.keyvault.keys.crypto import SignatureAlgorithm
import os


def sign_payload(payload_data, key_name=None):
    key_id = os.environ.get("SIGNING_KEY_ID")
    if not key_id:
        raise ValueError("SIGNING_KEY_ID environment variable not set.")

    client = get_cryptography_client(key_id)
    # Azure Key Vault expects bytes for signing
    if isinstance(payload_data, str):
        payload_data = payload_data.encode('utf-8')

    # Use PS256 for signing with RSA key
    sign_result = client.sign(SignatureAlgorithm.ps256, payload_data)
    return {'signature': sign_result.signature, 'key_id': key_id, 'algorithm': 'PS256'}


def verify_signature(payload_data, signature, key_id):
    client = get_cryptography_client(key_id)
    if isinstance(payload_data, str):
        payload_data = payload_data.encode('utf-8')

    verify_result = client.verify(SignatureAlgorithm.ps256, payload_data, signature)
    return {'is_valid': verify_result.is_valid, 'key_id': key_id}

from security_client import get_text_analytics_client
from azure.ai.textanalytics import PiiEntityDomain, PiiEntityCategory

def check_payload_safety(decrypted_text):
    text_analytics_client = get_text_analytics_client()

    documents = [decrypted_text]

    # Detect PII entities in the text
    # You can specify specific domains and categories if needed
    # For a comprehensive check, we use the default PII detection
    response = text_analytics_client.recognize_pii_entities(documents, domain=PiiEntityDomain.PHI)

    unsafe_content_found = False
    pii_entities = []

    for doc in response:
        if not doc.is_error:
            for entity in doc.entities:
                unsafe_content_found = True
                pii_entities.append({
                    'text': entity.text,
                    'category': entity.category.value,
                    'subcategory': entity.subcategory,
                    'offset': entity.offset,
                    'length': entity.length
                })
        else:
            # Handle error for this document
            print(f"Error: {doc.id} - {doc.error.code} - {doc.error.message}")

    return {
        'unsafe_content_found': unsafe_content_found,
        'pii_entities': pii_entities,
        'original_text_length': len(decrypted_text)
    }
